-- =============================================================================================
-- RLS POLICIES — storage.objects (Supabase Storage RLS)
--
-- The service role is the ONLY writer outside quarantine (Decision #340, Q0.2 (a)). A client uploads
-- to `quarantine` through a signed upload URL and nowhere else; every other object is promoted,
-- cut or generated by the server, so no user JWT can put an unscanned file in a bucket, overwrite an
-- admitted one or delete one over the Storage API. One read contract per bucket, keyed on the first
-- path segment as the RLS anchor (storage.foldername(name))[1]. Buckets + their anchors are seeded in
-- 00005040_seed_storage_buckets.sql.
--
-- Enforcement tiers:
--   quarantine    - own upload only (INSERT + own SELECT); promotion is a service-role move
--   project       - read: projects.has_project_access({project_id})
--   messages      - read: comms.dm_participants membership on {thread_id}
--   personal      - read: owner = auth.uid() under users/{auth.uid()}
--   workspace     - read: active membership of the {entity_id} anchor (team OR business OR enterprise)
--   invoices      - read: owner on {owner_id}
--   verification  - NO authenticated policy at all → service-role ONLY (RLS-bypass)
--   public_assets - public read
--   avatars       - public read
--   showcase      - public read
--   catalogue     - public read
--   contact       - operator read of sent attachments
--
-- NOTE: multiple permissive SELECT policies on one bucket are OR-combined, so the project/messages
-- scoping below is written as the SOLE read policy for those buckets — do not re-add a broad
-- "any authenticated" read for them.
-- =============================================================================================


-- #region quarantine — virus-scan landing zone (own upload only)

-- The path's first segment is the uploader's own id — the anchor the bucket is documented to key on
-- and the prefix the upload pipeline mints (`{user_id}/{asset_id}/{name}`). Without it a user could
-- write objects under another user's prefix.
CREATE POLICY "Authenticated users can upload to quarantine" ON storage.objects FOR
INSERT
    TO authenticated
WITH
    CHECK (
        bucket_id = 'quarantine'
        AND auth.uid () = owner
        AND (storage.foldername (name)) [1] = auth.uid ()::text
    );

CREATE POLICY "Users can read their own quarantine files" ON storage.objects FOR
SELECT TO authenticated USING (
        bucket_id = 'quarantine'
        AND auth.uid () = owner
    );

-- #endregion


-- #region project — collaboration files, gated by projects.has_project_access() on {project_id}

CREATE POLICY "Project participants can read project files" ON storage.objects FOR
SELECT TO authenticated USING (
        bucket_id = 'project'
        AND projects.has_project_access (
            (storage.foldername (name)) [1]::uuid
        )
    );

-- #endregion


-- #region messages — global DM/inbox attachments, gated by comms.dm_participants on {thread_id}

CREATE POLICY "DM participants can read message attachments" ON storage.objects FOR
SELECT TO authenticated USING (
        bucket_id = 'messages'
        AND EXISTS (
            SELECT 1
            FROM comms.dm_participants dp
            WHERE
                dp.thread_id = (storage.foldername (name)) [1]::uuid
                AND dp.user_id = auth.uid ()
        )
    );

-- #endregion


-- #region personal — owner-only private drive

-- The uploader AND the path anchor (Decision #314): `personalLocation` keys the bucket
-- `users/{userId}/…`, so the anchor is the SECOND segment. Read only — the media pipeline admits a
-- library original here as the service role.
CREATE POLICY "Users read own personal files" ON storage.objects FOR
SELECT TO authenticated USING (
        bucket_id = 'personal'
        AND auth.uid () = owner
        AND (storage.foldername (name)) [1] = 'users'
        AND (storage.foldername (name)) [2] = auth.uid ()::text
    );

-- #endregion


-- #region workspace — entity-owned private drive, gated by ACTIVE MEMBERSHIP of the {entity_id} anchor
--
-- The entity counterpart of `personal`. Deliberately NOT `auth.uid() = owner`: an entity asset must
-- outlive the member who uploaded it, so the gate is membership of the anchor, not ownership of the
-- object. The three membership helpers are OR-ed because a single uuid anchor may name a team, a
-- business or an enterprise — the caller passes exactly one and the other two return false.
--
-- ⚠️ This is written as the SOLE policy for this bucket. Multiple permissive SELECT policies on
-- storage.objects are OR-combined, so adding a broad "any authenticated" read here would not
-- loosen `workspace` alone — do not add one (same warning as the project/messages buckets above).

CREATE POLICY "Entity members can read workspace files" ON storage.objects FOR
SELECT TO authenticated USING (
        bucket_id = 'workspace'
        AND (
            org.is_active_team_member (
                (storage.foldername (name)) [1]::uuid
            )
            OR org.is_active_business_member (
                (storage.foldername (name)) [1]::uuid
            )
            OR org.is_enterprise_member (
                (storage.foldername (name)) [1]::uuid
            )
        )
    );

-- #endregion


-- #region invoices — owner read on {owner_id}; NO authenticated write (service-role generates them)

CREATE POLICY "Owners can read their invoices" ON storage.objects FOR
SELECT TO authenticated USING (
        bucket_id = 'invoices'
        AND (storage.foldername (name)) [1] = auth.uid ()::text
    );

-- #endregion


-- #region verification — KYC/KYB docs: service-role ONLY.
-- Deliberately NO policy here. RLS is on (00002001) so `authenticated` is default-denied; only the
-- service_role (which bypasses RLS in Edge Functions) can read/write. Client uploads land in
-- `quarantine` and are promoted into `verification` by a SECURITY DEFINER / service-role move, so a
-- user's JWT never touches this bucket directly. Do NOT add an `authenticated` policy.
-- #endregion


-- #region [contact] contact — /contact attachments (Decision #276): operator read; SERVICE-ROLE write
-- A sender's file lands in `quarantine` like every upload; the contact pipeline (service role) sniffs
-- it and promotes the original to `contact/{user_id}/{asset_id}/{name}`. Operators read an object to
-- answer the request it was SENT with — its `files.items` row linked to one in
-- ops.contact_request_attachments, the same rule as files.fn_can_read's operator arm; a file its
-- sender removed or never sent is nobody's to read. Nobody else reads or writes this bucket, the
-- sender included (they keep their own copy). The sole policy, so no broader read can be
-- OR-combined in by accident.
CREATE POLICY "Operators read contact attachments" ON storage.objects FOR
SELECT TO authenticated USING (
        bucket_id = 'contact'
        AND security.is_admin ()
        AND EXISTS (
            SELECT 1
            FROM files.items i
            JOIN ops.contact_request_attachments a ON a.file_id = i.id
            WHERE i.bucket_id = 'contact'
              AND i.storage_path = objects.name
              AND i.deleted_at IS NULL
        )
    );
-- #endregion


-- #region public_assets — public read; SERVICE-ROLE write
-- Platform imagery under `platform/…` and re-hosted link favicons, written by the service role. No
-- client write (Decision #340, Q0.2 (a)): a world-readable bucket a user could PUT into would publish
-- an unscanned, unscreened file at a platform address.

CREATE POLICY "Public Assets are viewable by everyone" ON storage.objects FOR
SELECT TO public USING (bucket_id = 'public_assets');

-- #endregion


-- #region avatars — profile/team/business/enterprise branding: public read; SERVICE-ROLE write
--
-- Deliberately NO authenticated write policy (2026-09-22). Every object in this bucket is served to
-- the whole internet, so every object must have been through the quarantine scan and the media
-- pipeline — which writes here as the service role. The old "Owners can write their branding
-- assets" policy let any signed-in user PUT an arbitrary, unscanned file straight into a public
-- bucket over the Storage API, bypassing both.

CREATE POLICY "Avatars are viewable by everyone" ON storage.objects FOR
SELECT TO public USING (bucket_id = 'avatars');

-- #endregion


-- #region showcase — profile showcase stills + videos: public read; SERVICE-ROLE write
-- The same contract as `avatars`, for the same reason: the media pipeline is the only writer.

CREATE POLICY "Showcase media is viewable by everyone" ON storage.objects FOR
SELECT TO public USING (bucket_id = 'showcase');

-- #endregion


-- #region files.item_variants — the WebP tiers the pipeline wrote beside an asset
-- Placed with the storage policies because every row here describes a stored object. The read rule
-- is the parent asset's, through the one predicate the files.items policy also uses, so a tier can
-- never be readable when its original is not. No write policy: the pipeline writes as the service
-- role. RLS is enabled HERE, beside the policies — 00002001 does not list this table.
ALTER TABLE files.item_variants ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Variants follow their asset" ON files.item_variants FOR
SELECT TO authenticated USING (files.fn_can_read (item_id));

CREATE POLICY "Public variants are viewable by everyone" ON files.item_variants FOR
SELECT TO anon USING (
    EXISTS (
        SELECT 1 FROM files.items i
        WHERE i.id = item_id AND i.visibility = 'public'::files.file_visibility AND i.deleted_at IS NULL
    )
);

-- #endregion


-- #region catalogue — marketplace storefront media: public read; SERVICE-ROLE write
-- The same contract as `avatars` (Decision #340, Q0.2 (a)): storefront media is served to the whole
-- internet, so the server publishes it from an admitted library original; no seller writes here.

CREATE POLICY "Catalogue media is viewable by everyone" ON storage.objects FOR
SELECT TO public USING (bucket_id = 'catalogue');

-- #endregion
